package io.coolbox.opt;
import com.sun.jna.Pointer;import com.sun.jna.ptr.DoubleByReference;import io.coolbox.internal.ErrorBuffer;import io.coolbox.internal.Matrices;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Python {@code opt} aggregation functions. */
public final class Owa {
 private static final OptNative N=OptNative.INSTANCE;private static final AtomicLong IDS=new AtomicLong(1000);private static final ConcurrentHashMap<Long,LayerLoss> LOSSES=new ConcurrentHashMap<>();
 @FunctionalInterface public interface LayerLoss { double evaluate(double[][] layers); }
 private Owa(){}
 private static int cols(double[][] a){return Matrices.columns(a);}
 private static void config(OwaConfig c) {if(c==null)throw new NullPointerException("config");}
 public static double[] naiveAverageParameters(double[][] local){int n=cols(local);double[] out=new double[n];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_owa_naive_average(Matrices.flatten(local),local.length,n,out,e.pointer(),e.capacity()));return out;}
 public static OwaResult optimalWeightedAverageLinearRegression(double[][] local,double[][] features,double[] targets,OwaConfig config){config(config);int m=local.length,p=cols(local),f=cols(features);if(targets.length!=features.length)throw new IllegalArgumentException("validation feature and target counts differ");double[] merged=new double[p],weights=new double[m];DoubleByReference loss=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_owa_linear_regression(Matrices.flatten(local),m,p,Matrices.flatten(features),features.length,f,targets,targets.length,config.mergeIterations,config.learningRate,config.l2Regularization,config.projectToSimplex?1:0,merged,weights,loss,e.pointer(),e.capacity()));return new OwaResult(merged,weights,loss.getValue());}
 public static OwaCrossValidationResult fastOwaCrossValidationLinearRegression(double[][] local,double[][][] foldFeatures,double[][] foldTargets,OwaConfig c){config(c);if(foldFeatures.length!=foldTargets.length)throw new IllegalArgumentException("fold counts differ");int m=local.length,p=cols(local),folds=foldFeatures.length,fc=cols(foldFeatures[0]);long[] ro=new long[folds+1],to=new long[folds+1];int rows=0,nt=0;for(int i=0;i<folds;i++){if(cols(foldFeatures[i])!=fc||foldFeatures[i].length!=foldTargets[i].length)throw new IllegalArgumentException("invalid fold dimensions");rows+=foldFeatures[i].length;nt+=foldTargets[i].length;ro[i+1]=rows;to[i+1]=nt;}double[][] all=new double[rows][fc];double[] y=new double[nt];int at=0,yt=0;for(int i=0;i<folds;i++){for(double[] r:foldFeatures[i])all[at++]=r.clone();System.arraycopy(foldTargets[i],0,y,yt,foldTargets[i].length);yt+=foldTargets[i].length;}double[] losses=new double[folds];DoubleByReference mean=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_owa_cross_validation_linear_regression(Matrices.flatten(local),m,p,Matrices.flatten(all),ro,y,to,folds,fc,c.mergeIterations,c.learningRate,c.l2Regularization,c.projectToSimplex?1:0,losses,mean,e.pointer(),e.capacity()));return new OwaCrossValidationResult(mean.getValue(),losses);}
 public static double[] weightedTensorAverage(double[][] local,double[] weights,long... shape){int m=local.length;long size=1;for(long s:shape)size*=s;for(double[] t:local)if(t.length!=size)throw new IllegalArgumentException("tensor shape mismatch");double[] merged=new double[(int)size];ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_owa_weighted_tensor_average(flatten(local),m,shape,shape.length,weights,size,merged,e.pointer(),e.capacity()));return merged;}
 public static NowaResult nonlinearOptimalWeightedAverageLayers(double[][][] models,LayerLoss loss,OwaConfig c){config(c);if(models.length==0)throw new IllegalArgumentException("models must not be empty");int modelCount=models.length,layers=models[0].length;long[] shapes=new long[layers],shapeOff=new long[layers+1],sizes=new long[layers],valueOff=new long[layers+1],dims=new long[layers];int all=0;for(int l=0;l<layers;l++){int sz=models[0][l].length;shapes[l]=sz;sizes[l]=sz;dims[l]=1;shapeOff[l+1]=l+1;valueOff[l+1]=all+sz;all+=sz;for(int m=1;m<modelCount;m++)if(models[m].length!=layers||models[m][l].length!=sz)throw new IllegalArgumentException("layer dimensions mismatch");}double[] flat=new double[modelCount*all];for(int m=0;m<modelCount;m++){int at=m*all;for(int l=0;l<layers;l++){System.arraycopy(models[m][l],0,flat,at,models[m][l].length);at+=models[m][l].length;}}long id=IDS.getAndIncrement();LOSSES.put(id,loss);OptNative.NowaLoss cb=(user,v,sizesPtr,count,out)->{try{long[] ss=new long[(int)count];for(int i=0;i<ss.length;i++)ss[i]=sizesPtr.getLong(i*Long.BYTES);double[] raw=v.getDoubleArray(0,(int)Arrays.stream(ss).sum());double[][] ls=new double[ss.length][];int at=0;for(int i=0;i<ss.length;i++){ls[i]=Arrays.copyOfRange(raw,at,at+(int)ss[i]);at+=(int)ss[i];}out.setValue(LOSSES.get(Pointer.nativeValue(user)).evaluate(ls));return 1;}catch(Throwable t){return 0;}};double[] merged=new double[all],weights=new double[modelCount*layers];DoubleByReference val=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();try{e.check(N.coolbox_owa_nonlinear_layers(flat,modelCount,layers,shapes,shapeOff,sizes,valueOff,dims,c.mergeIterations,c.learningRate,c.l2Regularization,c.projectToSimplex?1:0,cb,Pointer.createConstant(id),merged,weights,val,e.pointer(),e.capacity()));}finally{LOSSES.remove(id);}double[][] result=new double[layers][];int at=0;for(int l=0;l<layers;l++){result[l]=Arrays.copyOfRange(merged,at,at+(int)sizes[l]);at+=sizes[l];}double[][] layerWeights=new double[layers][modelCount];for(int l=0;l<layers;l++)System.arraycopy(weights,l*modelCount,layerWeights[l],0,modelCount);return new NowaResult(result,layerWeights,val.getValue());}
 private static double[] flatten(double[][] arrays){int total=0;for(double[] a:arrays)total+=a.length;double[] out=new double[total];int at=0;for(double[] a:arrays){System.arraycopy(a,0,out,at,a.length);at+=a.length;}return out;}
}


